  delete from pb_ai.kb_chunks where version = 'b3e91f6c47d2' and ord >= 3239 and chunk->>'id' in ('osha-pl-trench-states-1', 'fed-811-wait-1', 'fed-811-ticketlife-1', 'fed-811-zone-1');
  get diagnostics vk = row_count; if vk <> 4 then raise exception 'FAIL: % new rows deleted', vk; end if;
  update pb_ai.kb_chunks set ord = -1 - ord where version = 'b3e91f6c47d2';
  update pb_ai.kb_chunks k set ord = m.o from (select o, (row_number() over (order by o) - 1)::int as n from generate_series(0, 3269) o where o <> all(array[270,271,302,2383,2788,2989,3205,3206,3207,3208,3209,3210,3211,3212,3213,3214,3215,3216,3217,3218,3219,3220,3221,3222,3223,3224,3225,3226,3227,3228,3254])) m
   where k.version = 'b3e91f6c47d2' and k.ord = -1 - m.n;
  get diagnostics vk = row_count; if vk <> 3239 then raise exception 'FAIL: % rows moved back', vk; end if;
  update pb_ai.kb_chunks k set lib = e->>1, chunk = e->2 from jsonb_array_elements($kb$[[1992, "field", {"id": "trench-safety-1", "url": "https://www.osha.gov/trenching-excavation", "text": "Under OSHA's excavation standard (29 CFR 1926.652), workers in an excavation must be protected from cave-ins by a protective system (sloping, benching, shoring or a shield/trench box) unless the excavation is made entirely in stable rock, or is less than 5 ft deep and a competent person has examined the ground and found no sign of a potential cave-in. Excavations 20 ft deep or more need a protective system designed by a registered professional engineer (or based on tabulated data approved by one). OSHA's trenching page stresses that trench collapses kill workers every year and that a cubic yard of soil can weigh as much as a car. Never enter an unprotected trench 5 ft or deeper (4 ft or deeper in Washington, WAC 296-155-657), and don't assume shallow trenches are safe. Some state plans are stricter than federal OSHA; your competent person and company program decide. This is a plain-language explanation, not the regulation; the OSHA text governs.", "title": "Trench safety: when a protective system is required", "topic": "Trench and excavation safety (plain-language guidance)", "source": "OSHA Trenching and Excavation safety topic page", "confidence": "high"}], [2835, "field", {"id": "dig-basics-1", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.651", "text": "Every state has a one-call law and 811 reaches the right center from anywhere in the country. The steps are the same everywhere: mark your dig area in white, call or go online before you dig, wait the legal notice time, check that every utility has marked or answered, dig by hand or vacuum inside the tolerance zone, keep the marks visible, and renew the ticket before it runs out. What changes by state is the numbers. Of the 51 state tables in the app (50 states and DC, checked 2026-11-19): the wait is 2 working days in 28 states and 3 in 13, and longer in a few; ticket life runs from about two weeks to 60 days, counted in working days in some states and calendar days in others, and from the call in some and from the legal dig date in others; the tolerance zone is 18 inches each side in about as many states as 24 inches, measured from the mark in some and from the outside edge of the line in others. So never carry one state's numbers to the next job: ask for your job's state by name (for example 'how long is a ticket good for in Texas'), or open Locates and tap Rules for the state. Federal OSHA adds its own duty in every state: find out where underground lines are before opening an excavation, and protect, support or remove them while it is open (29 CFR 1926.651(b)). The ticket, the 811 center and the state law govern; this is a plain-language summary.", "title": "811 before you dig: what is the same everywhere and what changes by state", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "State one-call laws as listed in the app's state rules table (51 rows, checked 2026-11-19); 29 CFR 1926.651(b)", "confidence": "high"}], [2839, "field", {"id": "plan-trench-depth-1", "url": "https://www.osha.gov/stateplans", "text": "Federal OSHA requires a protective system (sloping, benching, shoring or a shield) in an excavation 5 ft or deeper unless it is entirely in stable rock, and in a shallower one when the competent person sees a cave-in hazard (29 CFR 1926.652). Twenty-one states run their own OSHA plan for private construction crews; a plan must be at least as protective as federal and may be stricter, so on those jobs cite the state rule. What has been checked against the state's own rule text so far (as of 2026-11-20): Washington requires protection at 4 ft and, since June 1, 2026, a written trench work plan and a competent person on site during trench work; California keeps 5 ft and adds a Cal/OSHA permit for excavations 5 ft or deeper that people enter; Michigan uses its own Part 9 (slope or support over 5 ft, with its own angle table); Arizona, Nevada, New Mexico, Oregon and Utah adopt the federal excavation standard, so 5 ft; Alaska, Kentucky, Minnesota and Tennessee adopt the federal rule and Hawaii, North Carolina and Virginia list no excavation rule of their own (from OSHA's and the agencies' pages, not each state code read line by line), so 5 ft; South Carolina uses the federal text and adds training to the competent person definition. Not yet checked: Indiana, Iowa, Maryland (a state supplement to the federal rule exists and was not read), Vermont and Wyoming; treat federal 5 ft as the floor there and ask the state agency or your safety person whether the plan adds anything. In every state the competent person and your company program decide what protection a trench gets.", "title": "State OSHA plans and trench protection depth: which rule book applies on your job", "topic": "State OSHA plans: where trench and confined space rules differ from federal OSHA", "source": "29 CFR 1926.652(a)(1); osha.gov/stateplans; Wash. Admin. Code 296-155-657; 8 CCR 341; Mich. Admin. Code R 408.40941; AZ R20-5-601; UT R614-1-4; OR 437-003-0001; NM 11.5.3.9 NMAC; checked 2026-11-20", "confidence": "medium", "supersedes": "plan-trench-depth-1"}], [2841, "field", {"id": "dig-ca-penalties-1", "url": "https://california.public.law/codes/ca_gov't_code_section_4216.6", "kind": "summary", "text": "California fines for breaking the dig law (Gov. Code 4216.6(a)): a negligent violation, up to $10,000; a knowing and willful violation, up to $50,000; a knowing and willful violation that damages a gas or hazardous liquid line and lets flammable, toxic or corrosive gas or liquid escape, up to $100,000. Who enforces: the Contractors State License Board for contractors; the Public Utilities Commission for gas, electric and water corporations; the State Fire Marshal for hazardous liquid pipelines; local boards for local agencies; and the Underground Safe Excavation Board (\"Dig Safe Board\") for everyone else, since July 1, 2020. The Attorney General or a district attorney can also sue. On top of fines, the excavator can owe the repair cost and other damages. A contractor's license can be on the line with the CSLB. The Board also investigates near misses and damages reported to it.", "tier": "core", "state": "CA", "title": "California 811: the fine for digging without calling 811, and who enforces", "topic": "811 penalties, exemptions and design tickets", "source": "Cal. Gov. Code 4216.6 (california.public.law copy, section updated Jan 1, 2025)", "checked": "2026-11-20", "edition": "Section as updated January 1, 2025", "license": "gov-state", "confidence": "high"}], [2979, "field", {"id": "sp-ca-trench-1", "url": "https://dir.ca.gov/Title8/1541_1.html", "kind": "summary", "text": "California (Cal/OSHA) requires a protective system for each employee in an excavation unless it is made entirely in stable rock, or it is less than 5 feet deep and a competent person's examination of the ground finds no sign of a potential cave-in (8 CCR 1541.1(a)(1)). That is the same 5 ft test as federal OSHA. California's sloping table (8 CCR 1541.1 Appendix B) has the same slopes as the federal one. What California adds is a permit: 8 CCR 1539 sends excavation and trench permits to 8 CCR 341, which requires a Cal/OSHA permit before building a trench or excavation 5 ft or deeper into which any person is required to descend (341(d)(5)(A)); trenches for emergency repair of underground facilities are exempt (341(e)). The trench shield rule matches the federal one: dig no more than 2 feet below the bottom of the support (8 CCR 1541.1(e)(2)(A)).", "tier": "core", "state": "CA", "title": "California trench protection depth and the Cal/OSHA excavation permit", "topic": "State safety plan: trench and excavation", "source": "8 CCR 1541.1(a)(1), (e)(2)(A); 8 CCR 1539; 8 CCR 341(d)(5)(A), (e)", "checked": "2026-11-20", "edition": "Title 8 CCR, section text read 2026-11-20 (Register 2011, No. 50)", "license": "gov-state", "confidence": "high"}], [2981, "field", {"id": "sp-ca-trench-other-1", "url": "https://dir.ca.gov/title8/1541.html", "kind": "summary", "text": "California's 8 CCR 1541 keeps the federal numbers for the everyday trench rules: a stairway, ladder, ramp or other safe way out in trenches 4 feet or deeper, within 25 feet of lateral travel (1541(c)(2)); air testing before entering excavations deeper than 4 feet where oxygen under 19.5 percent or a hazardous atmosphere could reasonably be expected (1541(g)(1)(A)); spoil, materials and equipment at least 2 feet from the edge or held back by retaining devices (1541(j)(2)); and daily inspections by a competent person before work, as needed during the shift and after rain (1541(k)(1)). Crossings are worded differently: walkways or bridges with standard guardrails are required where employees or equipment cross over excavations more than 6 feet deep and wider than 30 inches (1541(l)(1)); remote excavations, wells, pits and shafts are barricaded or covered (1541(l)(2)). The federal crossing rule has no width (29 CFR 1926.651(l)).", "tier": "core", "state": "CA", "title": "California trench ladders, air testing, spoil setback and crossings", "topic": "State safety plan: trench and excavation", "source": "8 CCR 1541(c)(2), (g)(1)(A), (j)(2), (k)(1), (l)(1)-(2)", "checked": "2026-11-20", "edition": "Title 8 CCR, last amended operative 5-31-2012 (Register 2012, No. 18)", "license": "gov-state", "confidence": "high"}], [2987, "field", {"id": "sp-wa-trench-1", "url": "https://lawfilesext.leg.wa.gov/Law/WAC/WAC%20296%20%20TITLE/WAC%20296%20-155%20%20CHAPTER/WAC%20296%20-155%20-657.htm", "kind": "summary", "text": "Washington (L&I, DOSH) requires a protective system for each employee in an excavation unless it is made entirely in stable rock, or it is \"less than 4 feet (1.22m) in depth and examination of the ground by a competent person provides no indication of a potential cave-in\" (WAC 296-155-657(1)(a)). So in this state the depth is 4 ft, one foot shallower than the federal 5 ft in 29 CFR 1926.652(a)(1). The 2 ft rules match federal: dig no more than two feet below the bottom of a support system or a shield, and only if it is designed for the full depth and no soil is being lost (296-155-657(5)(b), (7)(b)). The state's sloping table (Table N-1, WAC 296-155-66403) has the federal slopes but no short-term 1/2 to 1 Type A row (read by an earlier check on 2026-11-20). An engineer designs slopes over 20 ft.", "tier": "core", "state": "WA", "title": "Washington trench protection starts at 4 feet", "topic": "State safety plan: trench and excavation", "source": "WAC 296-155-657(1)(a), (5)(b), (7)(b); WAC 296-155-66403 Table N-1", "checked": "2026-11-20", "edition": "WAC 296-155-657, WSR 16-09-085, effective 5/20/2016", "license": "gov-state", "effective": "2016-05-20", "confidence": "high"}], [3003, "field", {"id": "sp-mn-trench-1", "url": "https://www.dli.mn.gov/sites/default/files/pdf/fact_trenching_excavation.pdf", "kind": "summary", "text": "Minnesota (MNOSHA) adopts the federal excavation rules, 29 CFR 1926.651 and 1926.652, so trench protection is required from 5 ft, or shallower when a competent person sees signs of a possible cave-in; MNOSHA's trenching fact sheet states no state difference (read by an earlier check on 2026-11-20). Confined space in construction is also the federal rule, 29 CFR 1926 Subpart AA: the old state construction rule, Minn. R. 5207.0300 to 5207.0304, is marked repealed (42 SR 1015; read 2026-11-19). MNOSHA's page of differences from federal OSHA lists nothing for excavation or confined space. Injury reporting times and any state heat rule were not read; they are not confirmed here.", "tier": "core", "state": "MN", "title": "Minnesota trench and confined space rules: the federal text", "topic": "State safety plan: trench and excavation", "source": "MNOSHA trenching fact sheet; Minn. R. 5207.0300-.0304 (repealed, 42 SR 1015); MNOSHA differences page", "checked": "2026-11-20", "edition": "MNOSHA fact sheet and differences page, read 2026-11-20", "license": "gov-state", "confidence": "medium", "unconfirmed": "yes"}], [3022, "field", {"id": "sp-md-who-1", "url": "https://labor.maryland.gov/labor/mosh/moshspecific.shtml", "kind": "summary", "text": "Maryland's plan, MOSH, lists its state-specific regulations in COMAR Title 09, Subtitle 12: employee injury and illness records (09.12.21), fall protection in steel erection (09.12.25), crane safety (09.12.26), tower crane operator certification (09.12.27), tree care (09.12.28), heat stress (09.12.32), access to information on hazardous and toxic substances (09.12.33), field sanitation (09.12.36) and personnel platforms on cranes (09.12.38). The same MOSH page lists Maryland supplements to federal standards, including 29 CFR 1926.651 (excavations), 29 CFR 1926.1201 to 1213 (confined spaces in construction), 29 CFR 1926.62 (lead) and Subpart CC (cranes). The text of the excavation and confined space supplements was not read on 2026-11-20, so what they add is not confirmed: the federal 5 ft trench rule is the floor, and a crew should read the MOSH supplement or ask MOSH. The old state confined space rule (COMAR 09.12.35) was repealed effective January 2, 2017.", "tier": "core", "state": "MD", "title": "Maryland: MOSH-specific rules and supplements to the federal trench rule", "topic": "State safety plan: who enforces and what differs", "source": "MOSH, Maryland-specific standards page; COMAR 09.12.21-09.12.38", "checked": "2026-11-20", "edition": "MOSH page, read 2026-11-20", "license": "gov-state", "confidence": "medium", "unconfirmed": "yes"}]]$kb$::jsonb) e where k.version = 'b3e91f6c47d2' and k.ord = (e->>0)::int;
  get diagnostics vk = row_count; if vk <> 9 then raise exception 'FAIL: % rows put back', vk; end if;
  insert into pb_ai.kb_chunks (version, ord, lib, chunk) select 'b3e91f6c47d2', (e->>0)::int, e->>1, e->2 from jsonb_array_elements($kb$[[270, "field", {"id": "ca-cal-osha-trench-and-confined-1", "url": "https://www.dir.ca.gov/title8/341.html", "text": "In California, before anyone builds a trench or excavation 5 feet or deeper into which a person is required to descend, the employer must hold a Cal/OSHA permit (Title 8, section 341(d)): either an annual permit covering the company's trenching for the year or a project permit for one job. 'Descend' means entering any part of the excavation once it is 5 ft or deeper. Federal OSHA has no such permit; this is a California rule on top of the excavation rules in Title 8 sections 1540 to 1541.1. The permit comes from the Cal/OSHA district office (application per section 341.1 and fee); an annual permit holder must also notify the Division each time it starts permit work at a new site. The safety lead usually holds it; the permit number belongs on the job's paperwork because an inspector will ask. Exempt (341(e)): government bodies, PUC-regulated utilities, emergency repair of underground facilities, excavations nobody has to enter, graves and pools. The permit does not replace the competent person, daily inspections or the protective system. If you are not sure the company has one, ask the office before the trench goes past 5 ft.", "title": "Cal/OSHA permit for trenches 5 ft or deeper (8 CCR 341): California only", "topic": "Cal/OSHA (Title 8) rules for trenches and confined spaces in California", "source": "8 CCR 341(c), (d), (e) and 341.1 (Cal/OSHA permit requirements)", "confidence": "high"}], [271, "field", {"id": "ca-cal-osha-trench-and-confined-2", "url": "https://www.dir.ca.gov/title8/1541.html", "text": "California's excavation standard is Title 8 Construction Safety Orders Article 6: 1539 (permits), 1540 (definitions), 1541 (general requirements) and 1541.1 (protective systems, with Appendices A to F matching the federal ones). The numbers track federal 1926.651 and 1926.652: protective system at 5 ft or deeper unless the cut is entirely in stable rock (a competent person can waive it only for a trench under 5 ft that shows no indication of a potential cave-in); ladder, stairway or ramp within 25 ft of lateral travel in trenches 4 ft or deeper (1541(c)); spoil and equipment at least 2 ft back from the edge (1541(j)); daily competent-person inspections (1541(k)); atmosphere tested before entry into excavations deeper than 4 ft where a hazard could exist, limits 19.5 percent oxygen and 20 percent of the LFL (1541(g)); same soil types and slopes, appendix options to 20 ft, engineer beyond. California adds: the one-call step in 1541(b) (notify the regional notification center 2 working days ahead, no digging until the area is marked and every operator has given a positive response, onsite meeting within 10 ft of a high priority installation) and the 5 ft permit in section 341. The app's OSHA library carries the federal text; cite Title 8 in California.", "title": "Title 8 §1540-1541.1: Cal/OSHA's excavation rules and how they match federal Subpart P", "topic": "Cal/OSHA (Title 8) rules for trenches and confined spaces in California", "source": "8 CCR 1539, 1540, 1541(b), (c), (g), (j), (k), 1541.1 compared with 29 CFR 1926.650-652", "confidence": "high"}], [302, "field", {"id": "ca-dig-alert-4216-9", "url": "https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=GOV&sectionNum=4216.6.", "text": "California enforces its one-call law through several agencies (Gov Code 4216.6(c) to (e)): the Contractors State License Board for licensed contractors, the Public Utilities Commission for gas, electric and water corporations, the State Fire Marshal for hazardous liquid pipeline operators, and, since July 1, 2020, the Underground Facilities Safe Excavation Board (the Dig Safe Board, under the Office of the State Fire Marshal) for everyone else; the board also investigates and recommends. Civil penalties in 4216.6(a): up to $10,000 for a negligent violation; up to $50,000 for a knowing and willful violation; up to $100,000 for a knowing and willful violation that damages a gas or hazardous liquid pipeline and lets flammable, toxic or corrosive gas or liquid escape. Repair costs and injury claims are separate. Typical violations: digging without a valid ticket, digging before every operator has responded, machine digging inside the tolerance zone, no delineation, not reporting damage. For the crew this means: a current ticket number on the daily report, photos of the marks before digging, and a record of hand-dig potholes near every marked line.", "title": "California one-call penalties and the Dig Safe Board (Gov Code 4216.6)", "topic": "Utility locates in California: Gov Code 4216, DigAlert and USA North 811", "source": "California Government Code 4216.6(a), (b), (c), (d), (e)", "confidence": "high"}], [2383, "field", {"id": "cal-1", "text": "In California, a contractor needs a Cal/OSHA (DOSH) excavation permit before digging any trench or excavation 5 ft or deeper into which a person must descend (Title 8, section 341). It is an annual permit or a one-job project permit; an annual permit holder also notifies the DOSH district office before starting each such job. Greenbook 306-3.1 repeats the requirement. The usual excavation rules still apply: a competent person inspects daily and after rain, protection (sloping, shoring or a shield) at 5 ft and deeper, spoils at least 2 ft back from the edge, and a ladder or ramp within 25 ft of lateral travel in trenches 4 ft or deeper.", "title": "Cal/OSHA trench permit (5 ft and deeper)", "topic": "Cal/OSHA rules crews run into", "source": "Cal. Code Regs. tit. 8, section 341 and section 1541; Greenbook 306-3.1 (California)"}], [2788, "field", {"id": "dig-ca-overview-1", "url": "https://codes.findlaw.com/ca/government-code/gov-sect-4216-2/", "kind": "summary", "text": "California's dig law is Government Code 4216 to 4216.24. Two centers answer 811: USA North 811 (north and central) and DigAlert (south). Mark the dig area in white first: the law says the excavator \"shall delineate the area to be excavated\" before calling. Call at least 2 working days and not more than 14 calendar days before digging. Working days are Monday to Friday, 7 AM to 5 PM, not holidays, and the call day does not count. Do not dig until every operator on the ticket has marked or answered through electronic positive response. A ticket is good for 28 days from issue; renew by the end of day 28. If it expires while work goes on, stop and get a new ticket. Tolerance zone: 24 inches on each side of the field mark. Inside it, find the line with hand tools before using power equipment. Hit a line: call the operator right away; call 911 if gas or hazardous liquid is escaping; tell the 811 center within 48 hours.", "tier": "core", "state": "CA", "title": "California 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (USA North 811, DigAlert)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Cal. Gov. Code 4216, 4216.2, 4216.3, 4216.4, 4216.6 (FindLaw copy, current as of Jan 1, 2026)", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "license": "gov-state", "confidence": "high", "supersedes": "dig-ca"}], [2989, "field", {"id": "sp-wa-trench-other-1", "url": "https://lawfilesext.leg.wa.gov/Law/WAC/WAC%20296%20%20TITLE/WAC%20296%20-155%20%20CHAPTER/WAC%20296%20-155%20-655.htm", "kind": "summary", "text": "Washington's WAC 296-155-655 keeps the federal numbers for most everyday trench rules: a safe way out in trenches four feet or more deep within 25 feet of lateral travel (3)(b); air testing before entering excavations greater than four feet deep where oxygen deficiency or a hazardous atmosphere could reasonably be expected (7)(a)(i); materials and equipment at least two feet from the edge (10)(b); and daily inspections by a competent person, and after every rainstorm (11)(a). One number is stricter: guardrails are required \"where walkways are four feet or more above lower levels\" (12), where the federal crossing rule uses 6 feet (29 CFR 1926.651(l)). Utilities are located before opening the excavation and found exactly by safe and acceptable means as digging gets close (2).", "tier": "core", "state": "WA", "title": "Washington trench ladders, air testing, spoil and walkway guardrails", "topic": "State safety plan: trench and excavation", "source": "WAC 296-155-655(2), (3)(b), (7)(a)(i), (10)(b), (11)(a), (12)", "checked": "2026-11-20", "edition": "WAC 296-155-655 as amended by WSR 26-09-113, effective 6/1/2026", "license": "gov-state", "effective": "2026-06-01", "confidence": "high"}], [3205, "field", {"id": "sp-al-trench-1", "url": "https://www.osha.gov/stateplans", "kind": "summary", "text": "Alabama has no state OSHA plan that covers private employers, so federal OSHA covers private construction crews there (OSHA list of State Plans). Trench protection: a protective system (sloping, benching, shoring, or a trench box / shield) is required in an excavation 5 ft or deeper unless it is entirely in stable rock, and in a shallower one when the competent person sees signs of a possible cave-in (29 CFR 1926.652(a)(1)). There is no separate Alabama trench depth rule for private crews in the library; the competent person decides what protection the trench gets.", "tier": "core", "state": "AL", "title": "Alabama trench protection depth: the federal OSHA rule, 5 feet (trench box, shoring, sloping)", "topic": "State safety plan: trench and excavation", "source": "29 CFR 1926.652(a)(1); OSHA State Plans list (osha.gov/stateplans); app state table checked 2026-11-19", "checked": "2026-11-20", "edition": "29 CFR 1926 Subpart P as in force 2026-11-20", "license": "gov-us", "confidence": "medium"}], [3206, "field", {"id": "sp-ar-trench-1", "url": "https://www.osha.gov/stateplans", "kind": "summary", "text": "Arkansas has no state OSHA plan that covers private employers, so federal OSHA covers private construction crews there (OSHA list of State Plans). Trench protection: a protective system (sloping, benching, shoring, or a trench box / shield) is required in an excavation 5 ft or deeper unless it is entirely in stable rock, and in a shallower one when the competent person sees signs of a possible cave-in (29 CFR 1926.652(a)(1)). There is no separate Arkansas trench depth rule for private crews in the library; the competent person decides what protection the trench gets.", "tier": "core", "state": "AR", "title": "Arkansas trench protection depth: the federal OSHA rule, 5 feet (trench box, shoring, sloping)", "topic": "State safety plan: trench and excavation", "source": "29 CFR 1926.652(a)(1); OSHA State Plans list (osha.gov/stateplans); app state table checked 2026-11-19", "checked": "2026-11-20", "edition": "29 CFR 1926 Subpart P as in force 2026-11-20", "license": "gov-us", "confidence": "medium"}], [3207, "field", {"id": "sp-co-trench-1", "url": "https://www.osha.gov/stateplans", "kind": "summary", "text": "Colorado has no state OSHA plan that covers private employers, so federal OSHA covers private construction crews there (OSHA list of State Plans). Trench protection: a protective system (sloping, benching, shoring, or a trench box / shield) is required in an excavation 5 ft or deeper unless it is entirely in stable rock, and in a shallower one when the competent person sees signs of a possible cave-in (29 CFR 1926.652(a)(1)). There is no separate Colorado trench depth rule for private crews in the library; the competent person decides what protection the trench gets.", "tier": "core", "state": "CO", "title": "Colorado trench protection depth: the federal OSHA rule, 5 feet (trench box, shoring, sloping)", "topic": "State safety plan: trench and excavation", "source": "29 CFR 1926.652(a)(1); OSHA State Plans list (